import {calculate} from './model.mjs';
const $=s=>document.querySelector(s);
const groups=[
{title:'What does your workload look like?',description:'Use benchmarked throughput for a representative workload mix. Rates count physical attempts, including retries.',fields:[
['demand','Current request rate','req/s','Incoming physical traffic, including retry attempts.',null],
['growth','Demand growth','req/s²','Additional requests per second, each second. Enter 0 for flat demand.',null],
['tested','Tested throughput per replica','req/s','Benchmark throughput before applying operating headroom.',null],
['util','Target operating factor','%','70% keeps 30% of tested throughput as headroom.',70],
['replicas','Existing replicas','count','Existing workers before this scaling decision.',null],
['readyPercent','Average readiness contribution','%','100% = all existing replicas are fully routable.',100]]},
{title:'How long until capacity is useful?',description:'Enter an end-to-end readiness quantile, such as p95, including scheduling, startup, warm-up, health checks and routing.',fields:[
['delay','Readiness delay (e.g. p95)','sec','Time from detecting the need to safely routable capacity.',null],
['margin','Extra trigger margin','sec','Additional lead-time buffer; also extends the forecast horizon.',20],
['minimum','Minimum replicas','count','Resilience floor required by your policy.',2],
['maximum','Maximum permitted replicas','count','Lowest of dependency, budget and platform replica limits.',30],
['dependency','Dependency throughput ceiling','req/s','Maximum fleet admission supported by downstream dependencies.',null],
['queue','Maximum queue depth','work','Count limit for work whose contract permits deferral.',5000],
['wait','Maximum queue-wait budget','sec','Fluid estimate only; not a per-request deadline guarantee.',2],
['queued','Work already queued','work','Existing queued work consumes available queue room.',0]]},
{title:'What must remain safe?',description:'Accepted-work counts apply to one potential drain candidate. Optional topology and latency inputs add planning checks.',fields:[
['active','Active operations on candidate','count','Accepted operations still executing.',0],
['unresolved','Unresolved effects on candidate','count','Writes whose final outcome is not yet known.',0],
['sessions','Pinned sessions on candidate','count','Sessions that have not completed or migrated.',0]],extras:[
{title:'Region and availability-zone capacity',fields:[['regions','Active Regions','count','Symmetric topology assumption.',2],['azs','AZs per Region','count','Active availability zones in each Region.',3],['azCapacity','Safe capacity per AZ','req/s','Enter a benchmarked value; 0 skips this check.',0],['regionLoss','Tolerated Region losses','count','Regions unavailable at the same time.',1],['azLoss','AZ losses per surviving Region','count','Conservative additional failures in every surviving Region.',1]]},
{title:'Latency and concurrency planning',fields:[['latency','Service latency objective','ms','Used as a concurrency-planning allowance, not a measured mean.',140],['edge','Edge / gateway allocation','ms','Combined routing and authorization budget.',15],['app','Application logic allocation','ms','Application processing budget.',15],['db','Synchronous database allocation','ms','Include any cross-Region commit step.',80],['response','Response allocation','ms','Serialization and response handling.',5],['latencyMargin','Latency safety margin','ms','Unallocated headroom.',25]]}]}];
const all=groups.flatMap(g=>[...g.fields,...(g.extras||[]).flatMap(e=>e.fields)]);
const example={demand:2500,growth:8,tested:500,util:70,replicas:8,readyPercent:100,delay:110,margin:20,minimum:2,maximum:30,dependency:10000,queue:5000,wait:2,queued:0,active:0,unresolved:0,sessions:0,regions:2,azs:3,azCapacity:30000,regionLoss:1,azLoss:1,latency:140,edge:15,app:15,db:80,response:5,latencyMargin:25};
let values={},step=0,last=null,dirty=false;
const fmt=(v,d=0)=>Number.isFinite(v)?v.toLocaleString(undefined,{maximumFractionDigits:d}):'Not reached';
const field=([id,label,unit,help])=>`<div class="field" data-field="${id}"><label for="${id}">${label}</label><div class="input-wrap"><input id="${id}" name="${id}" type="number" min="0" step="any" inputmode="decimal" value="${values[id]??''}" placeholder="Enter value" aria-describedby="help-${id}"><span class="unit">${unit}</span></div><p class="help" id="help-${id}">${help}</p></div>`;
function drawForm(){const g=groups[step];$('#fields').innerHTML=`<h3 class="step-heading">${g.title}</h3><p class="step-description">${g.description}</p><div class="field-grid">${g.fields.map(field).join('')}</div>${(g.extras||[]).map(e=>`<details class="extra"><summary>${e.title}</summary><div class="field-grid">${e.fields.map(field).join('')}</div></details>`).join('')}`;
document.querySelectorAll('[data-step]').forEach(b=>{const selected=+b.dataset.step===step;b.classList.toggle('selected',selected);if(selected)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');});
$('#back').hidden=step===0;$('#next').hidden=step===2;$('#calculate').hidden=step!==2;$('#error').textContent='';
$('#fields').querySelectorAll('input').forEach(el=>el.addEventListener('input',()=>{values[el.name]=el.value;dirty=true;if(last)render(last.p,last.r);}));}
function missing(list){return list.find(([id])=>values[id]===''||values[id]===null||values[id]===undefined);}
function next(){const bad=missing(groups[step].fields);if(bad){$('#error').textContent=`Please enter ${bad[1].toLowerCase()}.`;$('#'+bad[0]).focus();return;}step++;drawForm();}
function loadExample(){values={...example};step=0;drawForm();$('#sample-note').textContent='Paper example loaded. All values are editable; these are design inputs, not measured results.';compute();}
function reset(){values=Object.fromEntries(all.map(f=>[f[0],f[4]??'']));last=null;dirty=false;step=0;drawForm();$('#sample-note').textContent='Enter your own values, or load the paper example to get started.';$('#output').hidden=true;$('#empty').hidden=false;}
function compute(){const bad=missing(all);if(bad){step=groups.findIndex(g=>[...g.fields,...(g.extras||[]).flatMap(e=>e.fields)].some(f=>f[0]===bad[0]));drawForm();$('#error').textContent=`Please enter ${bad[1].toLowerCase()}.`;const el=$('#'+bad[0]);el.closest('details')?.setAttribute('open','');el.focus();return;}
try{const p=Object.fromEntries(Object.entries(values).map(([k,v])=>[k,Number(v)]));const r=calculate(p);dirty=false;last={p,r};render(p,r);$('#empty').hidden=true;$('#output').hidden=false;}catch(e){$('#error').textContent=e.message;}}
function chart(p,r){const W=510,H=210,L=51,R=15,T=18,B=32;const end=Math.max(1,r.horizon*1.3,p.delay*1.35);const max=Math.max(1,p.demand+p.growth*end,r.capacity,r.after)*1.2;const x=t=>L+t/end*(W-L-R),y=v=>H-B-v/max*(H-T-B);const a=Math.min(p.delay,Math.max(0,p.growth?(r.mu-p.demand)/p.growth:(p.demand>r.mu?0:p.delay)));let grid='';for(let i=0;i<4;i++){const v=max*i/3;grid+=`<line x1="${L}" x2="${W-R}" y1="${y(v)}" y2="${y(v)}" stroke="#e5eae4"/><text x="${L-8}" y="${y(v)+3}" text-anchor="end" font-size="9" fill="#687b7b">${fmt(v)}</text>`;}return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Linear demand versus available admission capacity, with new replicas arriving at ${p.delay} seconds"><title>Projected demand and admission capacity</title>${grid}<polygon points="${x(a)},${y(r.mu)} ${x(p.delay)},${y(r.mu)} ${x(p.delay)},${y(p.demand+p.growth*p.delay)} ${x(a)},${y(p.demand+p.growth*a)}" fill="#f4e1cb"/><path d="M ${x(0)} ${y(r.mu)} H ${x(p.delay)} V ${y(r.after)} H ${x(end)}" fill="none" stroke="#126d62" stroke-width="2.5"/><path d="M ${x(0)} ${y(p.demand)} L ${x(end)} ${y(p.demand+p.growth*end)}" fill="none" stroke="#bc8555" stroke-width="2.5"/><line x1="${x(p.delay)}" x2="${x(p.delay)}" y1="${T}" y2="${H-B}" stroke="#95a9a0" stroke-dasharray="3 4"/><text x="${Math.min(W-95,x(p.delay)+5)}" y="${T+8}" fill="#687b7b" font-size="9">Capacity arrives</text><text x="${L}" y="${H-10}" fill="#687b7b" font-size="9">Now</text><text x="${x(p.delay)}" y="${H-10}" text-anchor="middle" fill="#687b7b" font-size="9">${fmt(p.delay)} s</text><text x="${W-R}" y="${H-10}" text-anchor="end" fill="#687b7b" font-size="9">${fmt(end)} s</text></svg>`;}
function render(p,r){let headline=r.conflict?'Resolve conflicting limits':r.replicaShortfall?'Capacity is constrained':r.urgency&&r.scaleOut?'Add capacity and bridge the gap':r.scaleOut?'Plan additional capacity':'Current count covers the target';
const lead=r.conflict?'The minimum replica requirement exceeds the hard maximum. No feasible target exists.':r.scaleOut?`Plan for ${fmt(r.target)} replicas total — ${fmt(r.scaleOut)} more than the existing fleet. Newly requested workers count only after readiness.`:`The calculated target is ${fmt(r.target)} replicas. Any reduction requires stable demand, failure-domain checks and a completed drain.`;
const warns=[];if(r.replicaShortfall)warns.push(`${r.replicaShortfall} replicas below required capacity: the hard maximum binds.`);if(r.after<r.predicted)warns.push('Post-arrival admission is below forecast demand. A persistent bottleneck remains; the bridge estimate covers only the pre-arrival interval.');if(p.readyPercent<100)warns.push('Existing partial readiness is held constant in this model. Validate its measured contribution and future warm-up.');
$('#output').innerHTML=`${dirty?'<div class="stale">Inputs changed. Recalculate to update these results. <button class="text-button" id="recalculate">Recalculate ↗</button></div>':''}<div class="result-header"><div class="result-top"><p class="eyebrow">YOUR SCALING PLAN</p><span class="badge">${r.conflict?'Infeasible':r.urgency?'Lead time at risk':'Planning estimate'}</span></div><h2>${headline}</h2><p>${lead}</p></div><div class="metrics"><div class="metric"><label>Safe fleet capacity</label><strong>${fmt(r.capacity)}</strong><small>requests / second</small></div><div class="metric"><label>Replica target</label><strong>${fmt(r.target)}</strong><small>${r.conflict?'infeasible floor':fmt(r.raw)+' required by demand'}</small></div><div class="metric"><label>Time to saturation</label><strong>${Number.isFinite(r.saturation)?fmt(r.saturation,1):'∞'}</strong><small>${Number.isFinite(r.saturation)?'seconds at current growth':'not reached at flat demand'}</small></div></div><div class="result-body"><div class="section-title"><h3>Demand vs. available capacity</h3><span>${fmt(r.horizon)} s planning horizon</span></div><div class="legend"><span>Admission capacity</span><span>Projected demand</span></div><div class="chart">${chart(p,r)}</div><p class="footnote">${fmt(r.safe)} safe req/s per replica · ${fmt(r.predicted)} forecast req/s · Readiness ratio ${r.ratio===null?'not defined':fmt(r.ratio,2)}. Ratio ≤ 1 indicates insufficient lead time. The chart assumes any planned additions arrive together.</p><div class="bridge"><div class="section-title"><h3>Temporary overload bridge</h3><span>${fmt(r.deficit)} operations of deficit</span></div><div class="bridge-bar"><span class="defer" style="width:${r.deficit?r.defer/r.deficit*100:0}%"></span><span class="reject" style="width:${r.deficit?r.rejected/r.deficit*100:0}%"></span></div><div class="bridge-values"><div><strong>${fmt(r.defer)}</strong>Within deferral budget</div><div><strong>${fmt(r.rejected)}</strong>Reject, backpressure or degrade</div></div><p class="footnote">Admission ceiling: ${fmt(r.mu)} req/s. Deferral requires an explicit operation contract; queue room is bounded by ${fmt(p.queue)} work items and a ${fmt(p.wait,2)} s wait allowance.</p></div><div class="checks">${warns.map(t=>`<div class="check warn">⚠ ${t}</div>`).join('')}<div class="check ${r.drainClear?'':'warn'}"><b>Drain candidate:</b> ${r.drainClear?'No active work, unresolved effects or pinned sessions were entered. This is necessary, not sufficient, for safe termination.':`${fmt(p.active)} active operations, ${fmt(p.unresolved)} unresolved effects and ${fmt(p.sessions)} pinned sessions. Do not terminate this candidate.`}</div><div class="check ${p.azCapacity&&r.survivor<p.demand?'warn':''}"><b>Failure-domain check:</b> ${p.azCapacity?`${fmt(r.survivor)} req/s survives the configured failures; ${r.survivor>=p.demand?'covers':'does not cover'} current demand. This does not establish write quorum or availability.`:'Not evaluated. Enter tested safe capacity per AZ to enable this check.'}</div><div class="check ${r.latencyBudget>p.latency?'warn':''}"><b>Latency budget:</b> ${fmt(r.latencyBudget)} ms allocated against a ${fmt(p.latency)} ms objective. ${r.latencyBudget>p.latency?'Budget exceeds the objective.':'Allocation fits; actual p95 must still be measured.'} Planning concurrency: approximately ${fmt(r.concurrency)} in-flight operations.</div></div><div class="report-actions"><button id="download" class="secondary" ${dirty?'disabled':''}>Download results ↓</button><button id="print" class="text-button">Print plan ↗</button></div><p class="footnote">Estimates, not deployment guarantees. This calculator does not initiate scaling, admit requests, or verify transaction state.</p></div>`;
$('#recalculate')?.addEventListener('click',compute);$('#print').onclick=()=>window.print();$('#download').onclick=()=>{const data=JSON.stringify({model:'linear-step-capacity-v1',generatedAt:new Date().toISOString(),parameters:p,results:r,notes:'Planning estimates only. null saturation means not reached with flat demand. No live infrastructure is connected.'},(k,v)=>typeof v==='number'&&!Number.isFinite(v)?null:v,2);const url=URL.createObjectURL(new Blob([data],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='scaling-plan.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
$('#next').onclick=next;$('#back').onclick=()=>{step--;drawForm();};$('#planner').onsubmit=e=>{e.preventDefault();if(step<2)next();else compute();};document.querySelectorAll('[data-step]').forEach(b=>b.onclick=()=>{step=+b.dataset.step;drawForm();});$('#example').onclick=loadExample;$('#try-example').onclick=loadExample;$('#reset').onclick=reset;reset();
